/**
 * Help of the Discord server: slash commands and the topic of each channel.
 * Single source for the /ajuda command, the slash command registration and docs/discord-canais.md
 * (generated by `npm run docs:discord`). A channel topic holds at most 1024 characters.
 */
export type CanalId = 'briefing' | 'alertas' | 'aprovacoes' | 'reunioes' | 'pessoas' | 'cto' | 'planejamento' | 'insights' | 'cobrancas';

export const LIMITE_TOPICO = 1024;
export const LIMITE_DESCRICAO_COMANDO = 100;

export interface OpcaoComando {
  nome: string;
  descricao: string;
  obrigatoria: boolean;
  escolhas?: string[];
}

export interface ComandoDef {
  nome: string;
  descricao: string;
  canais: CanalId[] | 'todos';
  opcoes: OpcaoComando[];
  exemplo: string;
}

