export const NOMES_CANAIS: Record<CanalId, string> = {
  briefing: '#briefing', alertas: '#alertas', aprovacoes: '#aprovacoes', reunioes: '#reunioes', pessoas: '#pessoas',
  cto: '#cto', planejamento: '#planejamento', insights: '#insights', cobrancas: '#cobrancas',
};

/** Whether the channel takes input from Paulo (the Copiloto reads it) or is output only. */
export const CANAIS_ENTRADA: CanalId[] = ['planejamento', 'insights', 'pessoas', 'cobrancas', 'reunioes'];

