/** Text answered by /ajuda for a channel: its topic plus the commands that work there. */
export function ajudaDoCanal(canal: CanalId): string {
  const cmds = COMANDOS.filter((c) => c.canais === 'todos' || c.canais.includes(canal));
  const lista = cmds.map((c) => `**/${c.nome}**: ${c.descricao}\n  Exemplo: \`${c.exemplo}\``).join('\n');
  return `**${NOMES_CANAIS[canal]}**\n${TOPICOS[canal]}\n\n${lista}`;
}
